def _rank_node(root, live, served, left, right):
    if root.owner != _epoch:
        return RankNode(root.key, live, served, left, right)
    root.live = live
    root.served = served
    root.left = left
    root.right = right
    lh = left.height if left else 0
    rh = right.height if right else 0
    root.height = 1 + (lh if lh > rh else rh)
    root.live_total = live + (left.live_total if left else 0) + (right.live_total if right else 0)
    root.served_total = served + (left.served_total if left else 0) + (right.served_total if right else 0)
    return root


def _rank_balance(root, left, right):
    lh = left.height if left else 0
    rh = right.height if right else 0
    if lh > rh + 1:
        ll, lr = left.left, left.right
        if (ll.height if ll else 0) >= (lr.height if lr else 0):
            new_right = _rank_node(root, root.live, root.served, lr, right)
            return _rank_node(left, left.live, left.served, ll, new_right)
        new_left = _rank_node(left, left.live, left.served, ll, lr.left)
        new_right = _rank_node(root, root.live, root.served, lr.right, right)
        return _rank_node(lr, lr.live, lr.served, new_left, new_right)
    if rh > lh + 1:
        rl, rr = right.left, right.right
        if (rr.height if rr else 0) >= (rl.height if rl else 0):
            new_left = _rank_node(root, root.live, root.served, left, rl)
            return _rank_node(right, right.live, right.served, new_left, rr)
        new_left = _rank_node(root, root.live, root.served, left, rl.left)
        new_right = _rank_node(right, right.live, right.served, rl.right, rr)
        return _rank_node(rl, rl.live, rl.served, new_left, new_right)
    return _rank_node(root, root.live, root.served, left, right)


def rank_add(root, key, live_delta, served_delta=0):
    # Zero-population ranks can remain: there are at most as many distinct
    # ranks on an active branch as enqueue commands in the entire request.
    if root is None:
        return RankNode(key, live_delta, served_delta)
    if key < root.key:
        return _rank_balance(root,
                             rank_add(root.left, key, live_delta, served_delta),
                             root.right)
    if key > root.key:
        return _rank_balance(root, root.left,
                             rank_add(root.right, key, live_delta, served_delta))
    return _rank_node(root, root.live + live_delta, root.served + served_delta,
                      root.left, root.right)


def live_less(root, key):
    total = 0
    while root is not None:
        if key <= root.key:
            root = root.left
        else:
            total += root.live + (root.left.live_total if root.left else 0)
            root = root.right
    return total


def served_greater(root, key):
    total = 0
    while root is not None:
        if key >= root.key:
            root = root.right
        else:
            total += root.served + (root.right.served_total if root.right else 0)
            root = root.left
    return total


def _rank_remove_many(node, ranks, lo, hi):
    if lo == hi:
        return node
    a, b = lo, hi
    while a < b:
        mid = (a + b) // 2
        if ranks[mid] < node.key:
            a = mid + 1
        else:
            b = mid
    cut = a
    end = cut
    while end < hi and ranks[end] == node.key:
        end += 1
    left = _rank_remove_many(node.left, ranks, lo, cut)
    right = _rank_remove_many(node.right, ranks, end, hi)
    return _rank_node(node, node.live - (end - cut), node.served, left, right)


def rank_remove_many(root, ranks):
    """Remove sorted resident ranks (duplicates allowed) in one tree walk."""
    return _rank_remove_many(root, ranks, 0, len(ranks))
